--
-- Table structure for table `farm_plot`
--

DROP TABLE IF EXISTS `farm_plot`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `farm_plot` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `plot_code` varchar(64) NOT NULL,
  `farmer_id` bigint unsigned NOT NULL,
  `plot_name` varchar(128) NOT NULL,
  `village` varchar(128) NOT NULL DEFAULT '丹邱村',
  `area_mu` decimal(10,2) NOT NULL,
  `variety` varchar(128) NOT NULL DEFAULT '增科新选丝苗1号',
  `longitude` decimal(10,7) DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `boundary_json` json DEFAULT NULL COMMENT '地块边界，前端地图展示用',
  `satellite_image_url` varchar(500) DEFAULT NULL COMMENT '静态卫星图地址',
  `status` enum('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `plot_code` (`plot_code`),
  KEY `fk_plot_farmer` (`farmer_id`),
  CONSTRAINT `fk_plot_farmer` FOREIGN KEY (`farmer_id`) REFERENCES `farmer_profile` (`id`),
  CONSTRAINT `chk_plot_area` CHECK ((`area_mu` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=416 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='农田地块';
/*!40101 SET character_set_client = @saved_cs_client */;

