--
-- Table structure for table `farm_record`
--

DROP TABLE IF EXISTS `farm_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `farm_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `plot_id` bigint unsigned NOT NULL,
  `season_id` bigint unsigned NOT NULL,
  `record_type` enum('SOWING','FERTILIZING','PESTICIDE','IRRIGATION','HARVEST','QUALITY_TEST') NOT NULL,
  `record_date` date NOT NULL,
  `description` text,
  `material_name` varchar(128) DEFAULT NULL,
