--
-- Table structure for table `farmer_profile`
--

DROP TABLE IF EXISTS `farmer_profile`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `farmer_profile` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `village` varchar(128) NOT NULL DEFAULT '丹邱村',
  `address` varchar(255) DEFAULT NULL,
  `id_card_masked` varchar(32) DEFAULT NULL COMMENT '仅保存脱敏身份证号',
  `certification_status` enum('PENDING','CERTIFIED','REJECTED','SUSPENDED') NOT NULL DEFAULT 'PENDING',
  `certification_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_id` (`user_id`),
  CONSTRAINT `fk_farmer_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='农户档案';
/*!40101 SET character_set_client = @saved_cs_client */;

