DROP TABLE IF EXISTS `field_inspection`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `field_inspection` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `plot_id` bigint unsigned NOT NULL,
  `inspector_id` bigint unsigned NOT NULL,
  `inspection_date` date NOT NULL,
  `result` enum('PASS','WARNING','FAIL') NOT NULL,
  `difference_note` text,
  `rectification_required` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_inspection_plot` (`plot_id`),
  KEY `fk_inspection_user` (`inspector_id`),
  CONSTRAINT `fk_inspection_plot` FOREIGN KEY (`plot_id`) REFERENCES `farm_plot` (`id`),
  CONSTRAINT `fk_inspection_user` FOREIGN KEY (`inspector_id`) REFERENCES `sys_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='政府实地核验记录';
/*!40101 SET character_set_client = @saved_cs_client */;

