  CONSTRAINT `fk_policy_product` FOREIGN KEY (`product_id`) REFERENCES `insurance_product` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=221 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='农户保单';
