--
-- Table structure for table `trace_code`
--

DROP TABLE IF EXISTS `trace_code`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `trace_code` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(96) NOT NULL,
  `plot_id` bigint unsigned NOT NULL,
  `season_id` bigint unsigned NOT NULL,
  `batch_name` varchar(128) NOT NULL,
  `product_grade` enum('SPECIAL','FIRST','SECOND') NOT NULL,
  `quality_report_url` varchar(500) DEFAULT NULL,
  `status` enum('ACTIVE','DISABLED') NOT NULL DEFAULT 'ACTIVE',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `fk_trace_plot` (`plot_id`),
  KEY `fk_trace_season` (`season_id`),
  CONSTRAINT `fk_trace_plot` FOREIGN KEY (`plot_id`) REFERENCES `farm_plot` (`id`),
  CONSTRAINT `fk_trace_season` FOREIGN KEY (`season_id`) REFERENCES `production_season` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=321 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='一批一码溯源码';
/*!40101 SET character_set_client = @saved_cs_client */;

